+/** Picks `ko` or `en` from an Accept-Language header (q-values, region tags); otherwise the fallback. */
+export function pickLanguage(header, fallback = config.defaultLanguage) {
+  const ranked = String(header ?? "")
+    .split(",")
+    .map((part, index) => {
+      const [tag, ...params] = part.trim().split(";");
+      const qParam = params.map((p) => p.trim()).find((p) => /^q=/i.test(p));
+      const q = qParam === undefined ? 1 : Number(qParam.slice(2));
+      return { lang: tag.trim().toLowerCase().split("-")[0], q: Number.isNaN(q) ? 0 : q, index };
+    })
+    .filter((x) => x.q > 0 && (x.lang === "ko" || x.lang === "en"))
+    .sort((a, b) => b.q - a.q || a.index - b.index);
+  return ranked.length ? ranked[0].lang : fallback;
+}
